# Own-wording items of Grim Hollow Player's Guide (2014 rules).
import importlib.util as _u, os as _o
_sp = _u.spec_from_file_location("tgh14p_item_w", _o.path.join(_o.path.dirname(_o.path.abspath(__file__)), "tgh14p_item_w.py")); _w = _u.module_from_spec(_sp); _sp.loader.exec_module(_w)
ITEMS = []; SP = {}; WPN = {}; GEAR = []; MASTERY = {}; WDESC = dict(_w.WDESC); WDESC_FN = _w.WDESC_FN; SWITCH_NOTE = ""
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))
CI = ["Charmed", "Frightened", "Paralyzed", "Poisoned", "Stunned"]
add("Angelskin Armor", "Armor", "Rare", 0, "Leather armor cut from the flayed skin of angels. While you wear it you are immune to Bludgeoning, Piercing and Slashing damage from nonmagical attacks, including nonmagical wooden or silvered weapons. Any celestial that sees the armor turns hostile to the wearer.", base=["Leather Armor"])
add("Ardor", "Weapon", "Artifact", 1, "A fiend's battleaxe with a +3 bonus to attack and damage. A hit deals an extra 3d10 Necrotic damage. While holding it you are immune to the Charmed, Frightened, Paralyzed, Poisoned and Stunned conditions. As a bonus action you can let it hover in an open space within 5 ft. While you see it, a bonus action commands it to fly 50 ft and either attack once or return to your hands. If an effect targets the hovering axe, you count as holding it. It falls if you die. While it is on you, an action casts bane, banishment, bestow curse, branding smite or incendiary cloud (save DC 18). Each spell can be cast once, then not again until the next dawn. Only its celestial twin Zeal can harm it. A creature wielding Zeal can attack Ardor, which has AC 21 and 300 hit points.", by="a fiend", fx={"atk": 3, "dmg": 3, "condImm": CI}, base=["Battleaxe"], xd=["Hit: +3d10 Necrotic"])
add("Armor of Zombie Flesh", "Armor", "Rare", 1, "Hide armor tanned from an animated zombie. While you wear it your AC is 16 plus your Dexterity modifier. You are proficient with it even if you lack hide armor proficiency.", by="a lich", base=["Hide Armor"])
add("Banshee Box", "Wondrous Item", "Uncommon", 1, "An ivory music box inlaid with tiny scenes of violence. When an attuned creature opens the lid, it can mentally set any sound for the box to play, such as eerie music, a lively party or endless screaming. The sound plays until the lid closes. Closing and reopening lets you choose a new sound. You choose whether it carries in a 5-ft, 30-ft or 120-ft radius. If the attuned user goes more than 300 ft away, the lid shuts and the music stops.", by="a spectre")
add("Blood Capsule", "Wondrous Item", "Uncommon", 0, "A cylindrical flask etched with necrotic runes. Humanoid blood kept in it stays fresh for up to a year. It holds enough blood to feed a vampire for one day.")
add("Bow of Four", "Weapon", "Very Rare", 1, "A white bow set with a ruby, emerald, sapphire and diamond. While holding it, you can summon a magical arrow of one element with no action. Choose air, earth, fire or water each time. An arrow not fired within 1 minute dissolves. On a hit, the air arrow deals 2d8 Lightning damage, the earth arrow 2d8 magical Bludgeoning, the fire arrow 3d8 Fire and the water arrow 2d8 Cold.", by="a primordial", base=["Longbow"], xd=["Air: 2d8 Lightning. Earth: 2d8 Bludgeoning. Fire: 3d8 Fire. Water: 2d8 Cold"])
add("Cinder Coat", "Armor", "Very Rare", 1, "A floor-length leather duster the color of dying embers. You have +1 AC while wearing it. It has 3 charges. When you hit a creature that is not at its hit point maximum, you can spend 1 charge to deal an extra 1d10 Fire damage. It regains 1d3 charges each dawn.", by="a fiend", fx={"ac": 1}, ch=[3, "1d3", "dawn"], base=["Leather Armor"])
add("Crimson Mist", "Wondrous Item", "Uncommon", 0, "A tiny bottle of prey pheromones, enough for one use. As an action, spray one target within 5 ft. The effect lasts 24 hours. A lycanthrope that fails its Lust for the Hunt save must prioritize a target affected by crimson mist over any other.")
add("Ectoplasmic Whip", "Weapon", "Rare", 1, "A whip of silver plasma that phases in and out of reality. You have +1 to attack and damage rolls with it. It is invisible to non-undead creatures. You have Advantage on attacks with it against creatures that cannot perceive it.", by="a spectre", fx={"atk": 1, "dmg": 1}, base=["Whip"])
add("Faerie Crown", "Wondrous Item", "Very Rare", 0, "A crown of fragrant flowers that draws butterflies. It has 1d6 + 3 butterflies hovering around it. When a weapon attack would hit you, use your reaction to release one. It takes the hit instead of you and is destroyed. When all are used, the crown withers and is destroyed.")
add("Fin Symbiote", "Wondrous Item", "Rare", 1, "A tendril of flesh from a living aboleth. To attune, stitch it onto your skin and leave it for the whole attunement period while it bonds with your muscles. While attuned you gain +2 to your Transformation Save DC. You cannot remove it or end attunement on your own. If it is cut off, it regrows in 1d4 hours.", by="an aberrant horror")
add("Funeral Mask", "Wondrous Item", "Uncommon", 1, "A thin copper mask that molds to the face. While wearing it you can use an action to change your appearance for 1 hour, including height, weight, features, voice, hair and distinguishing marks. You can look like another race but your statistics do not change. You cannot change size or basic shape. You can change the look again with an action. While disguised, your hideous appearance is hidden. After you use it, it cannot be used again until the next dawn.", by="a lich")
add("Heaven's Herald", "Wondrous Item", "Very Rare", 0, "A golden trumpet that never dulls. As an action, a good creature can blow it for a rousing song heard 600 ft away. The blower picks up to 12 allies in the area. Each is immune to Frightened, has Advantage on Wisdom saves, and its hit point maximum and current hit points rise by 2d10. This lasts 24 hours. After use, it cannot be used again until dawn. A neutral creature gets no sound. An evil creature must make a DC 15 Dexterity save as divine fire strikes down, taking 8d6 Radiant damage on a failure or half on a success.", ch=[1, "1", "dawn"])
add("Humble Frock", "Wondrous Item", "Uncommon", 1, "A rough, weather-worn frock full of holes. While a seraph wears it with no other armor or clothing, it automatically succeeds on checks to hide its divine appearance.", by="a seraph")
add("Hunter's Mutagen", "Potion", "Rare", 0, "A glowing green liquid that sends your antibodies into overdrive. When you drink it, you are immune to Poison damage and disease for 1 hour. You also cannot contract curses such as lycanthropy or mummy rot during that time. When the hour ends you gain one level of exhaustion.")
add("Iridescent Armor", "Armor", "Rare", 0, "A breastplate forged from a giant dragonfly's carapace, with a gossamer cape. You have +1 AC while wearing it. Once per day, use an action to turn the cape into dragonfly wings. They give you a fly speed of 60 ft for 1 hour. After that, it cannot be used again until the next dawn.", fx={"ac": 1}, ch=[1, "1", "dawn"], base=["Breastplate"])
add("Iron Fangs", "Wondrous Item", "Rare", 1, "Iron tooth caps inscribed with runes. If you shift into your hybrid or kindred form while wearing them, the metal grows over your teeth. Your bite attacks count as magical. You also cannot pass on lycanthropy through your bites.", by="a lycanthrope")
add("Light Drinker", "Weapon", "Very Rare", 1, "A longsword forged from one piece of black metal that drinks the light. You have +2 to attack and damage rolls with it, and it deals Cold damage instead of Slashing. While attuned you have darkvision 60 ft and see in magical darkness. As a bonus action it sheds magical darkness in a 15-ft radius with dim light for another 15 ft. While active, an action expands or shrinks the bright and dim radii by 5 ft each, up to 30 ft each and down to 10 ft each. Only antimagic field can suppress this darkness.", fx={"atk": 2, "dmg": 2, "dark": 60}, base=["Longsword"])
add("Lodestone Armor", "Armor", "Rare", 1, "Plate armor lined with lodestone from the plane of elemental earth. While wearing it, a bonus action boosts its magnetism. Loose stone, soil and minerals cling to it, giving +1 AC and reducing your speed by 5 ft. You can use the bonus action again each round, stacking up to +5 AC and a 25-ft speed reduction. If 1 minute passes with no activation, the material falls off and both effects end.", by="a primordial", base=["Plate Armor"])
add("Mortal Coil", "Ring", "Uncommon", 1, "A ring of hundreds of rose gold wires coiled around the finger. While a spectre wears it, a bonus action makes the spectre fully corporeal. It no longer registers as undead to magic and can touch the world like a normal humanoid. While corporeal it loses the benefits of its transformation. A bonus action returns it to its true form.", by="a spectre")
add("Profane Charm", "Wondrous Item", "Uncommon", 1, "A charred feather from a fallen angel, wrapped in silver wire. While wearing it you can enter hallowed ground without triggering your hideous appearance. The detect evil and good spell and a paladin's divine sense cannot detect you as a fiend.", by="a fiend")
add("Queen's Token", "Wondrous Item", "Legendary", 0, "A plain acorn, one of a faerie queen's mightiest gifts. While holding it you can use an action to cast wish. After that, the acorn teleports back to the queen who gave it. If the wish would be a threat to her or her realm in her eyes, it fails and the caster turns into an oak tree. Only a wish cast with the queen's token can undo it.")
add("Ring of Hidden Desire", "Ring", "Uncommon", 1, "A rose gold band set with a heart of obsidian. While wearing it, use an action to try to learn a creature's darkest desire. Choose a creature you see. It makes a DC 13 Wisdom save. On a failure you learn the desire. On a success you learn nothing and the creature is immune to the ring for 24 hours. A creature with Intelligence 3 or lower is unaffected.", by="a fiend")
add("Ring of Radiation", "Ring", "Uncommon", 1, "A ring of braided copper wire. While you wear it, your elemental energies radiate outward. Your reach with unarmed strikes increases by 5 ft.", by="a primordial")
add("Ring of Truth", "Ring", "Uncommon", 1, "A golden band stamped with smiling humanoid faces. While attuned, you constantly emit an aura like zone of truth, in a 15-ft radius sphere centered on you.")
add("Rod of Elemental Stasis", "Rod", "Rare", 1, "A wooden rod with four glass spheres, each holding a small world of elemental energy. If an air, fire, earth or water elemental dies within 60 ft of you while you hold it, the elemental is absorbed into one of the four crystals. If all are full, the elemental dies normally. As an action, show the rod and free one captured elemental. It appears within 5 ft, friendly to you and your allies, rolls initiative and takes its own turns. It obeys your spoken commands with no action from you. With no command it defends itself. It stays 10 minutes, until you dismiss it, or until it is slain, then returns to its home plane.", by="a primordial")
add("Rod of Ruin", "Rod", "Rare", 1, "A rod of stacked crystal spheres filled with smoke. It has 3 charges and regains all of them at dusk. When a creature you see within 60 ft damages you while you hold it, use your reaction and 1 charge to force a DC 15 Constitution save. On a failure the creature ages 2d10 years and gains one level of exhaustion.", by="a lich", ch=[3, "3", "dusk"])
add("Rod of the Pack Master", "Rod", "Very Rare", 1, "A driftwood rod carved with wolves and bears. While holding it, choose any number of willing creatures you see within 30 ft. You can hold it in your teeth, and it works in hybrid or kindred form. Each target becomes a wolf or a bear, depending on your lycanthrope heritage. It lasts 24 hours for each target, until you end it, or until the target drops to 0 hit points or dies. The target uses the beast's statistics but keeps its alignment, Intelligence, Wisdom and Charisma. It takes the beast's hit points and returns to its earlier hit points when it reverts. Excess damage from dropping to 0 carries over to the normal form without knocking it out unless that damage would drop the normal form to 0. The creature is limited to what its form can do and cannot speak or cast spells. Its gear melds into the new form.", by="a lycanthrope")
add("Second Skin", "Armor", "Rare", 1, "A harness woven from the hides of slain lycanthropes. In your hybrid form, it bonds to your flesh like a second pelt and your AC becomes 18. This replaces your usual Transformation AC. While wearing it you have Disadvantage on Charisma checks to interact with other lycanthropes.", by="a lycanthrope", base=["Hide Armor"])
add("Seeing Glass", "Wondrous Item", "Very Rare", 0, "An ornate silver hand mirror with a pattern of withered roses. Its reflection shows the true form of any creature in it, as if by true seeing. You can see invisible creatures, the true form of shapechangers, and the true face of creatures hiding their hideous appearance. If turned on a vampire, the glass shatters and is destroyed.")
add("Staff of the Sorcerer King", "Staff", "Legendary", 1, "An ebony staff with a bronze spear tip and blades carved as a winged scarab. It works as a magic spear with +2 to attack and damage rolls. You are proficient with it while attuned. You have +2 to spell attack rolls while holding it. Humanoids have Disadvantage on saves against your spells while you are attuned. You have Advantage on saves against spells that target only you. The staff is cursed and attunement passes the curse to you. Until remove curse or similar magic breaks it, you will not part with the staff and keep it within reach. You have Disadvantage on attack rolls with other weapons. Each midnight while attuned you must make a DC 17 Constitution save. On a failure your hit point maximum drops by 10 unless you are undead. Only wish restores it. If your maximum reaches 0, you die and rise as a wight.", by="a spellcaster", fx={"atk": 2, "dmg": 2}, base=["Spear"])
add("Stalk Symbiote", "Wondrous Item", "Uncommon", 1, "A tendril of flesh from a living aberration. To attune, stitch it onto your scalp and leave it for the attunement period while it bonds with your brain. While attuned you have Advantage on Wisdom (Perception) checks, and you and allies within 30 ft cannot be surprised unless incapacitated by something other than nonmagical sleep. You cannot remove it or end attunement on your own. If it is cut off, it regrows in 1d4 hours.", by="an aberrant horror")
add("Star Metal Ring", "Ring", "Rare", 1, "A heavy steel ring set with a chunk of shimmering star metal. While you wear it, your limbs are crusted with iridescent star metal. All your unarmed strikes deal magical damage.", by="an aberrant horror")
add("Stitching Needle", "Wondrous Item", "Rare", 0, "A black iron needle that pierces skin easily. If a creature's mouth is sewn shut with it, it cannot speak or cast spells with verbal components. It gains telepathy out to 60 ft. A creature you speak to this way does not need a shared language but must understand at least one. A creature without telepathy can receive and reply but cannot start a conversation with you. Sewing a willing, unconscious or incapacitated creature takes 10 minutes. Removing the stitches takes 1 minute.")
add("Straitjacket", "Wondrous Item", "Uncommon", 1, "A stained grey jacket with arms that reach the floor and dozens of straps. While an aberrant horror wears it, it rolls twice on the Unstable Mutations table and chooses the result. It takes 10 minutes to don or doff. A creature wearing it has Disadvantage on attack rolls.", by="an aberrant horror")
add("Sun Shades", "Wondrous Item", "Uncommon", 0, "Black leather goggles with cloudy glass that fully hide the eyes. While wearing them you do not have Disadvantage on attack rolls and ability checks made in sunlight. You also cannot see in complete darkness while wearing them, even with darkvision.")
add("Toadstool Toddy", "Potion", "Uncommon", 0, "A fizzy fuchsia drink that tastes of autumn rain, distilled from faerie magic. A fey who drinks it can last 3 extra days in an urban environment without exhaustion or rest penalties.")
add("Wand of the Poltergeist", "Wand", "Very Rare", 1, "A wand of twisted dark and white wood topped with a screaming skull. It has 7 charges. With it in hand, use an action to cast shatter (1 charge), major image (3 charges) or animate objects (4 charges) with no components. The save DC is your Transformation DC. It regains 1d6 + 1 charges each dusk. If you spend the last charge, roll a d20. On a 20 the wand explodes into splinters and is destroyed.", by="a spectre", ch=[7, "1d6+1", "dusk"])
SP["Wand of the Poltergeist"] = {"sp": [["Shatter", 0], ["Major Image", 0], ["Animate Objects", 0]]}
add("Watcher's Candle", "Wondrous Item", "Uncommon", 0, "A black taper that cannot be lit by hand. When a celestial, fiend, undead or fey comes within 120 ft, it lights with a purple flame and burns for 1 hour, after which it cannot be used again. It does not work wrapped in packaging or stowed in a container.")
add("Zeal", "Weapon", "Artifact", 1, "A seraph's warhammer with a +3 bonus to attack and damage. A hit deals an extra 3d10 Radiant damage. While holding it you are immune to the Charmed, Frightened, Paralyzed, Poisoned and Stunned conditions. As a bonus action you can let it hover in an open space within 5 ft. While you see it, a bonus action commands it to fly 50 ft and either attack once or return to your hands. If an effect targets the hovering hammer, you count as holding it. It falls if you die. While it is on you, an action casts banishment, branding smite, beacon of hope, earthquake or heroism (save DC 18). Each spell can be cast once, then not again until the next dawn. Only its fiendish twin Ardor can harm it. A creature wielding Ardor can attack Zeal, which has AC 21 and 300 hit points.", by="a seraph", fx={"atk": 3, "dmg": 3, "condImm": CI}, base=["Warhammer"], xd=["Hit: +3d10 Radiant"])
SP["Ardor"] = {"sp": [["Bane", 1], ["Banishment", 1], ["Bestow Curse", 1], ["Branding Smite", 1], ["Incendiary Cloud", 1]], "dc": 18}
SP["Zeal"] = {"sp": [["Banishment", 1], ["Beacon of Hope", 1], ["Branding Smite", 1], ["Earthquake", 1], ["Heroism", 1]], "dc": 18}
SP["Queen's Token"] = {"sp": [["Wish", 1]]}

